changeSet.sql:
INSERT INTO leave_type (id, company_id, name, label, max_days_per_year, carry_over_days, paid, requires_medical, active)
SELECT nextval('sequence_generator'), c.id, 'ANNUEL', 'Congé Annuel Payé', 18, 6, true, false, true
FROM company c
WHERE NOT EXISTS (
  SELECT 1 FROM leave_type lt WHERE lt.company_id = c.id AND lt.name = 'ANNUEL'
);

